   "goals": "본 수업은 일상생활 전반에서 자신의 강점을 활용해 정신건강을 향상시킬 수 있는 심리적 방법을 학습하고자 합니다. 정신건강이 무엇인지, 자기개념, 성격, 강점에 대해 알아보고, 스트레스를 효과적으로 대처할 수 있는 심리학 기반의 다양한 방법을 학습하는 것을 목표로 합니다.",
