   "textbook": "(주교재)특별한 주교재 없음. 교수가 제시하는 참고문헌을 활용할 것. (부교재1) 미셸 푸코 《성의 역사》1-3; 에두아르트 푹스 《풍속의 역사》1-4; 한스 리히트 《그리스 성 풍속사》1-2; 오토 키퍼 《로마 성 풍속사》1,2 등 다수",
