   "overview": "고대부터 근대까지 다양한 시대별 서양의 성과 풍속의 역사를 공부한다. 각 시대별로 신화와 동성애, 성매매와 전염병, 마녀 사냥과 성폭력 등 적절한 주제를 선정하여 소개한다.",
