   "overview": "기초 문자 및 언어문화로 히라가나를 가볍게 익히고, 정치, 경제, 종교, 의식주, 전통 및 현대 문화 등 주제별 탐구를 통해 일본 사회의 특징을 다각도로 이해한다. 한국문화와의 비교를 통해 일본 문화를 객관적으로 고찰하며, 학기 후반부 주제별 발표/토론을 진행한다.",
