   "overview": "본 교과목은 형법 전반에 대한 기초적인 이해를 목표로 하여 형법총론과 형법각론의 주요 내용을 균형 있게 다룬다. 범죄의 성립요건, 위법성, 책임, 미수범, 공범 등 형법의 기본체계를 이해하는 것이 중요하므로 형법총론을 중심으로 강의를 진행하고, 형법각론에서는 생명·신체, 재산, 자유 등에 관한 주요 범죄를 중심으로 핵심적인 내용을 학습한다.",
