   "overview": "건축은인문적인차원에서그리고하나의생각과사상으로써파악되어야한다.건축은그것을구현하는시공,구조,환경설비등의공학적인분야와밀접한관련을맺고있다.건축에서의목적은기술에있는것이아니라,건축그자체에있고,건축속에서인간의삶이이루어져왔으며지금도인간의삶이이루어지고있다.그리고인간의의지와미래지향의사고가건축에담겨있다. 이강좌에서는주변에서볼수있는건축물과평소관심을두는지역,장소를중심으로건축의발달과정,건축문화및인간과건축의관계에대해자세히살펴본다.",
