   "goals": "1. 오늘날 우리 생활의 저변에서 작동하고 있는 다양한 신화적 요소와 신화적 상상력을 이해하고, 그것이 인류 문화의 원천 역할을 하고 있음과 창조적 활동에 자양분을 제공하고 있음을 이해한다. 2. 본 강좌는 동서양 서사의 원형이 되는 신화의 구조 및 내용을 이해하고, 이를 통해 동서양 신화를 활용한 다양한 문화콘텐츠를 감상하는 능력을 기르고자 한다. 3. 신화를 활용한 다양한 문화콘텐츠 사례 학습을 통해 자신만의 시각으로 문화콘텐츠를 분석할 수 있는 능력을 함양한다.",
   "overview": "1. 동서양 각 문화권의 대표적인 신화를 통해 자연과 우주, 그리고 인간과 사회 문화에 끼치는 신화의 영향을 인식한다. 2. 동서양의 대표적인 창조·영웅·변신 신화 등을 중심으로 이들 신화적 사고가 인간사회와 문화적 산물에 어떻게 표현되고 있는지, 또한 각기 다른 문화가 신화적 주제를 차용하여 어떠한 방식으로 이해하여 문화콘텐츠로 활용하고 있는지 학습한다. 3. 동서양 신화를 현대적으로 재해석하여 제작된 다양한 문화콘텐츠의 글로벌 사례를 학습하고 신화로부터 유래하는 콘텐츠의 서사 구조와 특성을 구체적으로 살펴본다.",
