   "goals": "문학과 예술은 현대사회를 이해하는 핵심적인 영역 가운데 하나이며, 개인적일 뿐만 아니라 공공적이고 정치적인 양상을 띤다. 이 강좌는 사회문화사를 대상으로 삼은 문학과 예술작품들을 중심으로 한국의 근현대를 올바르게 이해할 수 있는 인문학적 교양을 함양하는 데 목적을 둔다. 이를 위해 문학과 예술에 대한 인식론적 기초에서부터 사회문화론의 시각과 방법, 문학과 예술의 이데올로기, 문학예술의 공시적ㆍ통시적 특성을 교수함으로써 한국사회를 읽어내는 새로운 인식의 지평을 추구하고자 한다.",
   "overview": "문학과 예술은 공동체 혹은 사회에 대한 상징적인 사유의 형식에 바탕을 두고 있는 까닭에 근현대 사회문화사를 형상화한 작품을 비평함으로써 학습자의 사회역사적 인식과 시각을 확장하는 데 초점을 맞춘다. ① 사회적 실천으로서 문학예술의 성격과 변화 양상을 읽어낸다. ② 문학예술과 시대정신, 문학예술과 정치ㆍ사회의 관계 양상을 이해함으로써 서양사회의 변화를 읽어낼 수 있는 시각을 기른다. ③ 문학과 예술을 통해 서양의 역사와 문화의 성격을 비판적으로 이해한다. ④ 서양사회사의 지배적인 흐름을 이해함으로써 당대를 살아가는 지식인으로서 필요한 시각과 인문학적 교양을 갖추도록 한다. ⑤ 문학과 예술을 통해 서양의 역사와 문화에 대한 이해를 드높임으로써 과거와 현재, 미래의 연계성을 강화한다.",
