   "textbook": "(주교재) 따로 주교재를 두지 않고 담당교수의 강의안을 중심으로 강의를 진행하고 여러 참고문헌을 활용한다. (부교재1) 이윤영 엮고 옮김, <사유 속의 영화>, 문학과지성사; 김성우 외, <청춘의 고전>, 알렙; 이병창, <반가워요, 베리만 감독님>, 먼빛으로; 벨라 바라즈, <영화의 이론>, 이형식 옮김, 동문선; 박병철, <생각의 창, 키노아이>, 서광사; 박성수, <들뢰즈>, 이룸; 김용규, <영화관 옆 철학카페>, 이론과 실천; 롤랑 바르크, <밝은 방>, 김웅권 옮김, 동문선; 조광제, <쉬르필로소피아>, 동녁; 루이스 자네티, <영화의 이해>, 박만준/진기행 역, k-books 등",
