   "overview": "영상에 대한 철학적 이해를 바탕으로 문화 표현으로서의 사진, 영화 등의 특성을 살피고, 개별 영상예술 작품(영화)을 분석하면서 우리 삶의 주요한 철학적 주제들을 다루어나간다. 우선, 이론적으로, 영화를 시각 매체 및 이미지 개념으로 고찰해 온 비평가와 철학자들의 논의를 바탕으로 영화의 매체적 특성과 철학적 의미를 간단히 탐구한다. 종국적으로, 영상 이미지를 통해 삶을 철학적으로 성찰하고, 우리 시대에 대두되는 주요한 삶의 문제들을 다양한 관점에서 재검토한다.",
