   "textbook": "주교재: <Anglo-American Culture> (Shinasa, 2017). 참고자료: Simon Jenkins, <A Short History of England>, Profile Books, 2012; <영국문화 바로 알기>, 최희섭·한일동 공저, 동인, 2018; <미국문화 바로 알기>, 최희섭 지음, 동인, 2013; 기타 The Guardian, The New York Times 등",
   "goals": "이 과목은 현재의 영미문화를 이해하기 위해 영미권의 역사, 사회, 정치 및 문화의 형성과 발전 과정을 영어로 읽고 분석한다. 이를 통해 학생들은 영어 독해 능력을 향상시키는 동시에 역사적 사건과 문화적 현상을 비판적으로 이해하고, 영미사회의 가치와 문화적 다양성을 폭넓게 해석하는 능력을 기른다.",
   "overview": "이 강의는 영미권의 역사와 문화를 다루는 영어 텍스트를 읽으며 영미문화의 주요 흐름을 이해하는 교양과목이다. 로마의 브리튼 지배와 노르만 정복, 마그나 카르타를 통한 민주주의의 발전, 제국주의와 식민주의, 미국의 건국과 남북전쟁, 흑인 민권운동, 냉전과 보수주의, 다문화주의에 이르기까지 영미사회의 형성에 중요한 영향을 미친 역사와 문화적 주제를 영어 원문을 통해 살펴본다.",
