   "overview": "이 과목은 인류 문화의 보고이자 예술의 중심지인 이탈리아의 문학, 미술, 영화, 음악, 패션, 건축을 통합적으로 탐구함으로써 보편적인 인간의 감정과 사유, 그리고 사회적 맥락을 인문학적 관점에서 이해하는 융합형 교양 과목이다. 학생들은 단테, 다 빈치, 미켈란젤로, 베르디, 칼비노 등 예술가들의 대표작을 감상하고 토론한다.",
