   "evaluation": "발표(40%), 과제물(40%), 토론(10%), 출결(10%)",
   "textbook": "*주교재 : 자체 교재. *참고문헌: 임지현, 『희생자의식 민족주의』, 휴머니스트, 2021; 마사 누스바움, 박용준 옮김, 『시적 정의』, 궁리, 2024; 오카 마리, 김병구 옮김, 『기억 서사』, 교유서가, 2024; 최인훈, <광장>, 『광장/구운몽』 문학과지성사, 2014; 박완서, 『그 많던 싱아는 누가 다 먹었을까』, 웅진지식하우스, 2025; 조해진, 『로기완을 만났다』, 창비, 2011; 『빛과 멜로디』, 문학동네, 2024 등",
   "goals": "이 강좌는 우리 사회의 민주적 대화와 타협의 가능성을 일상화하고, 극단적인 적대와 혐오의 정서에 대한 경각심을 키우는 계기로 전쟁을 다루는 다양한 문학·영상 서사에 대한 인문학적 접근 경로를 확보하고자 마련되었다.",
   "overview": "①인문학적 시각에서 조망하는 전쟁 자체에 대해 사유할 수 있는 방향을 고찰한다. ②전쟁 및 한국전쟁에 대한 공적 기념과 사적 기억의 층위를 다양한 서사를 통해 살펴본다. ③전쟁을 직접 경험한 세대와 전승을 통해 학습하는 세대 간의 편차를 논의한다. ④다양한 문학·영상 텍스트를 살펴보고 토의·토론하는 모둠 활동을 한다. ⑤주요 텍스트를 대상으로 감상문을 쓰고 공유한다.",
