   "goals": "지속적으로 변화하는 패션 트랜드에 주얼리가 중요한 요소로 장식될 수 있다. 본 교과 수강 후에는 풍부한 주얼리의 상품지식과 주얼리 산업체에 대한 기초·전문지식을 습득할 수 있으며 더 나아가 본 교양수업 후 주얼리 자격증 취득이 가능하다.",
