   "evaluation": "출석: 20%, 리포트: 30%, 기말시험: 40%, 발표 및 토론: 10%",
   "textbook": "(주교재) 부산대학교 한국민족문화연구소 편, [지역, 예술을 말하다], 소명출판, 2012. (부교재1) 부산대학교 한국민족문화연구소 편, [대중문화, 지역을 디자인하다], 소명출판, 2013.",
   "goals": "예술은 인간의 삶과 꿈을 다양한 방식으로 표현한다. 본 강좌는 현대 예술 속에서, 실제 우리의 모습 특히 지역에서 살고 있는 우리의 삶을 찾아보고자 한다. 우리와 동떨어진 것이 아닌, 지금 여기 우리의 모습이 현대 예술 속에서 어떻게 그려지고 있는가를 이해하는 데 본 강좌의 목적이 있다.",
   "overview": "본 강좌는 건축, 문학, 미술, 영화, 음악, 사진 등의 다양한 현대예술을 통해서 지역에서 살고 있는 대학생의 삶과 고민, 고민의 뿌리, 우리의 고민을 우리의 목소리로 표현해낼 수는 없는가 하는 것을 차례로 살펴볼 것이다. 특히, 공간적 위치가 우리의 현재와 미래의 삶에 어떤 영향을 끼치는지를 예술을 통해 살펴볼 것이다.",
