   "goals": "여름은 해가 다르게 더워지고 있다. 냉장고 없이 여름을 지낼 수 있을지를 생각해보자. 옛날 사람들은 더운 여름을 보낼 수 있었던 것은 '석빙고'를 만들어 얼음을 저장하여 이용하였기 때문에 가능하였다. 석빙고의 제작기술은 당시 과학기술의 수준을 보여준다. 이처럼 우리나라 전근대 시기에는 전통문화에 기반을 둔 과학과 기술이 이어져 왔다. 세계 다른 민족의 역사가 그러하듯이 우리 민족의 역사 발전을 제대로 이해하기 위해서는 과학기술의 발전을 빼놓을 수 없다. 전근대시기의 우리 민족은 석빙고의 경우처럼 특히 천문학, 기상학, 지리학, 의학 분야에서 뛰어난 성과를 이루었다. 우리가 자랑스럽게 널리 알리고, 재창조해야하는 과학 유산은 어떤 것이 있는가, 전자장치 없이 저절로 울리는 시계 자격루, 서적출판의 획기적인 계기가 되는 금속활자, 천문학 기상학이 뒷받침되어야 하는 해시계, 화약을 발명한 최무선, 우리나라 민족의학을 집대성한 허준에서 60만 마리의 나비를 채집한 석주명 박사에 이르기까지 다양한 내용과 문화유산들을 창출하였다. 이러한 우리나라의 과학기술의 발전은 과학발전을 이끈 선각자들이 있었고, 그들이 있었기 때문에 가능하였는데, 이들의 과학기술에 대한 집념을 아울러 살펴보고자 한다.",
   "overview": "본 강의는 한국의 과학기술을 문화사의 한 부분으로 이해하고, 선사시대부터 조선시대에 이르기까지 과학기술의 발전 과정을 역사적 맥락 속에서 살펴본다. 과학기술의 발전은 독립적으로 이루어지는 것이 아니라 다양한 문화와의 교류와 상호작용을 통해 형성된 결과임을 고찰한다. 또한 각 시대의 과학기술은 특정 인물의 천재성만으로 이루어진 것이 아니라, 당시의 사회적·문화적·지적 환경이 중요한 기반이 되었음을 이해하고자 한다. 나아가 세계 과학사의 흐름 속에서 한국 전통 과학기술의 특징과 위상을 함께 조명한다.",
