   "goals": "오늘날 인류는 급속한 산업화 및 정치적 이해관계로 인하여 자연자원 고갈의 위기에 직면에 있으며, 급변하는 지구환경의 변화로 대규모 자연재앙의 위협을 동시에 받고 있다. 따라서 현재 인류는 지구환경의 변화를 최소화하고 효율적이고 지속가능한 자원개발의 방안을 반드시 마련하여야 하는 상황이다. 이 강좌는 우리가 사용할 수 있는 자연자원의 특성을 이해하고 지구환경 보존과 함께 효율적이고 지속가능한 자원개발의 방향을 논의하는 데 목적이 있다.",
   "overview": "본 강의는 우선 물질과 에너지를 상호 교환하는 역동적인 여러 시스템으로 구성된 지구에 대하여 과학적 방법으로 접근하여 시스템 간의 상호작용을 더욱 정확히 이해하고자 한다. 또한, 인류가 이용하여 왔고 이용 가능한 자연자원인 광물자원, 화석에너지자원, 수자원, 지열 및 재생에너지와 같은 대체에너지자원 등의 본질적 특성과 지구환경과의 관련성을 공부하고, 현재와 미래 지구에서 이들 자원의 지속가능한 개발 및 이용에 관한 방안을 논의하고 토의한다.",
