   "goals": "본 강의는 비전공자를 대상으로 변화를 거듭해 온 고체 지구에 관한 기초적인 과학적 이해를 함양하는 것을 목표로 삼아, 지구의 형성과 내부 구조, 판 구조론의 기본 개념을 통해 영속 변화를 겪는 역동적인 행성으로서의 지구를 탐구한다. 특히 과거의 지질 기록 및 현시대에서 관찰할 수 있는 격변 사건을 조명함으로써 지질 현상과 생물권, 특히 인류 사이의 긴밀한 상호작용을 고찰한다. 궁극적으로, 현시대를 살아가는 인류의 구성원으로서 우리의 터전, 즉 지구에 관한 과학적 기초지식을 함양하고 재해에 대응하는 방법을 고민하는 것을 교수 목표로 삼는다. 특히, 과학적 배경을 기반으로 한 대중매체에서 이와 같은 자연 현상이 어떻게 다루어지고 있는지를 함께 살핀다.",
