   "overview": "지구시스템과 지질시대, 지권에 대한 기본적인 내용과 지질학에서의 통일이론인 판구조론의 기본 개념을 습득한다. 이를 통해 지진과 화산활동이 발생하는 지체구조적 환경 및 지진재해, 쓰나미, 화산과 함께 소행성 충돌 등의 토픽을 선별하여 강의를 진행한다. 강의를 통한 기본 개념의 습득 이후 지질사건 및 지구환경변화 사건들이 실제로 어떠한 변화를 야기하는지 다큐멘터리 및 사이언스 픽션 등의 시청각 자료를 통하여 체감 및 체득한다.",
