   "overview": "온라인 강의입니다. 이 수업은 「첨단분야 혁신융합대학사업(에너지신산업)」의 수행을 위해 개설되는 초급교과목으로서, 수업은 온라인 강의로 15주 동안 진행된다. 첫 8주는 지구와 지질환경의 이해, 전통에너지원의 형성 및 탄소순환에 미치는 영향 이해, 지구의 지질시대의 이해와 기후변화 원인에 대해 수업을 진행한다. 남은 주차의 수업은 지질환경의 특성을 활용한 탄소저감 방법을 이해하고 기후변화에 대응할 수 있는 기술에 대해 수업을 진행한다.",
