   "goals": "이 과목은 디지털 리터러시 교육을 통해 학생들이 융복합적 사고와 기초 디지털 역량을 갖추도록 하는 것을 목표로 합니다. (융복합 역량) 디지털 도구와 생성형 AI를 활용해 문서 작성, 데이터 분석 및 시각화를 학습하고, 협업 활동을 통해 융합적 사고와 창의적 문제 해결 능력을 키웁니다. (기초 지식 역량) 디지털 리터러시의 기본 개념을 이해하고, AI 기반 문서 작성과 데이터 시각화 실습을 통해 실무적 기초를 다집니다.",
   "overview": "\"디지털리터러시의 이해와 활용\" 과목은 현대 사회에서 필수적인 디지털 리터러시 역량을 배양하고, 생성형 AI를 비롯한 다양한 디지털 도구의 활용 능력을 강화하기 위해 설계되었습니다. 디지털 리터러시와 생성형 AI 활용 역량 강화를 목표로 설계된 과목이며, ChatGPT 등 AI 도구를 활용한 문서 작성, 정보 검색, 데이터 분석 및 시각화 실습, Microsoft Word/Google Docs/Notion 등 디지털 도구의 실무적 활용법 학습, 공공데이터 분석 및 시각화, 보고서 작성 및 발표 자료 제작, 협업 도구와 팀 프로젝트, 디지털 윤리 등을 다룬다.",
