   "goals": "프로그래밍으로 자동화할 수 있는 작업의 특성을 이해하고, 생성형 AI를 활용하여 효율적으로 문제를 해결하는 방법을 습득한다. 코딩 작업을 위한 프로그래밍 문제의 설계 방법을 이해하고, AI를 활용하여 알고리즘을 구성하고 최적화하는 능력을 배양한다. C언어를 이용하여 구체적인 프로그램을 설계하고 코딩하는 능력을 배양하며, 생성형 AI가 생성한 코드를 비판적으로 분석하고 개선하는 역량을 기른다.",
