   "goals": "1. 부산·경남 지역의 대표적인 문화유산을 통해 지역사의 흐름과 정치·경제·문화적 의미를 이해한다. 2. 문화유산 관련 장소를 직접 답사하며, 현장 체험을 통해 역사적 감수성과 지역 정체성을 함양한다. 3. 해양 도시 부산의 특성과 바다를 통한 대외 교섭의 역사적 의미를 조망한다. 4. 문화유산의 현재적 가치와 활용 방안을 고찰하고, 보존에 대한 공동체적 책임의식을 기른다.",
   "overview": "1. 부산과 경남 지역을 중심으로 우리 지역의 문화유산을 이해하고, 이를 통해 지역의 역사와 정체성을 탐색하는 것을 주된 목표로 한다. 2. 이론 강의와 현장 답사(트래킹)를 병행한다. 수강생은 2차례의 선택 답사 중 1회에 반드시 참여해야 한다. 3. 지역의 유형·무형 문화유산을 포괄적으로 다루되, 이를 역사·전통·유적·인물·문화 등으로 세분화하여 선사시대부터 현대까지의 흐름 속에서 조망한다. 4. 문화유산의 역사적 이해뿐 아니라 지리적 특성, 환경 조건, 지명의 유래 등 지역사 이해를 위한 기초적인 요소들도 함께 학습한다.",
