   "textbook": "(주교재)Jay Coakley(2007). Sports in Society : issues and controversies. McGraw-Hill. / (부교재1)임수원 외 (2006). 스포츠와 사회. 대구; 경북대학교 출판부 / 이상구, 강효민 (2001). 현대사회의 키워드 스포츠읽기. 서울 : 대한미디어. / Snyder, E. (1989). Social Aspects of Sport. / 지삼업 외 (2004). 새로운 스포츠사회학의 담론. 부산 : 제일출판인쇄 / 이근모 외(2005). 스포츠의사회학적 담론.",
