   "overview": "스포츠가 우리 사회에 어떤 의미인지, 무엇을 의미하는지에 대해 최종 결정을 내릴 수 있는 사람은 아무도 없습니다. 자신의 스포츠 참여와 관점에 대한 경험과 아이디어를 공유함으로써 학급 토론에 기여할 것으로 기대됩니다. 이는 여러분에게 더욱 즐거운 학습 경험을 제공할 뿐만 아니라 전체 수업에 시너지 효과가 있는 학습 환경을 조성합니다. 이 수업은 사실과 개념을 수동적으로 암기하도록 설계되지 않았습니다. 집단적 상호작용을 통해 우리는 스포츠 추구의 한 요소인 사회화 과정을 모방하게 됩니다.",
