   "textbook": "이 수업의 교재는 정해져 있지 않습니다. 스포츠와 관련된 이슈를 찾아낸 후 이슈를 해결하기 위한 방법을 다양한 자료를 통해 확인하는 것입니다. 논문, 신문기사, 동영상 등 어떠한 자료도 교재가 됩니다. 단, 발표에 사용된 모든 자료는 참고문헌을 기입해야 합니다.",
   "goals": "스포츠는 현대의 산물로써 우리의 삶 속에 깊이 침투해 있다. 즉, 스포츠 활동은 인간의 기본적인 의식주 활동과 더불어 중요한 활동의 하나로써 직접적인 참여에서 간접 참여까지 다양한 방식으로 경험하고 있는 것이다. 특히 스포츠의 대중화, 스포츠영웅의 탄생, 스포츠의 상품화 등과 같은 새로운 사회적 현상도 대두되고 있다. 이러한 시점에서 현대사회에서 스포츠의 역할, 기능, 문제점 등이 무엇인지를 스스로 고민해보고 스스로 탐색하여 발표하는 시간을 갖도록 한다.",
   "overview": "이 강의는 수강자 3~4인이 한 팀이 되어 스포츠와 관련된 이슈를 찾아내고, 이슈를 해결하기 위한 방법을 모색한 후 자료를 파워포인트로 발표하는 수업입니다. 발표 후 개인별로 질문을 하고 질문에 대한 답변을 마치면 조별 발표가 종료됩니다. 무엇보다 흥미로우면서도 전문성 있는 이슈를 발굴하는 것이 중요하고, 잘 요약하여 청중에게 잘 전달하는 것으로 평가받습니다.",
