   "overview": "오늘날 스포츠는 우리들의 생활에서 중요한 부분으로 자리매김하였다. 경제발전에 따른 생활수준의 향상과 여가 시간의 증대로 인하여 현대인은 여가를 선용하고 삶의 질을 향상시키기 위해 스포츠 활동에 참가한다. 또한, 올림픽, FIFA 월드컵, 윔블던 테니스 대회와 같은 메가 스포츠 이벤트를 포함한 다양한 스포츠 경기가 사람들에게 흥미 있는 볼거리를 제공하고 있다. 즉, 스포츠는 우리 사회 전반에 걸쳐 널리 퍼져 있고, 사회의 기본 제도라고 할 수 있는 가족, 교육, 정치, 경제, 대중매체, 종교는 물론 국제 외교까지 스포츠는 영향력을 미치고 있는 것이 사실이다. 따라서 본 강의에서는 현대사회에서 중요한 사회 현상 중 하나인 스포츠가 가지는 학문적 의미를 탐구하는 것이 주요 목적이다.",
