   "goals": "스포츠는 현대사회에서 인간의 삶에 깊이 침투한 사회문화적 산물로, 단순한 신체활동을 넘어 다양한 사회적, 경제적, 문화적 의미를 내포하고 있다. 1. 현대사회에서 스포츠가 수행하는 사회적 기능과 역할을 이해하고, 스포츠의 대중화, 상업화, 미디어화 현상을 통해 스포츠가 갖는 사회적 의미와 상징성을 분석한다. 2. 현대사회에서 나타나는 다양한 스포츠 이슈에 대해 분석하고, 이에 대한 자신의 견해를 제시할 수 있다. 3. 스포츠 현상과 관련된 참여 활동을 통해 이론과 현장학습을 실행한다.",
   "overview": "현대사회에서 스포츠는 단순한 여가 활동을 넘어 정치, 경제, 문화, 젠더, 미디어 등 다양한 사회적 구조와 상호작용하며 의미를 생산하고 재현한다. 본 강의는 스포츠와 사회 간 관계에 대한 이론적 기초를 이해하고, 다양한 사회 현상 속에서 일어나는 스포츠 현장에 대한 체험활동, 사회적 스포츠 이슈에 대한 토론 및 논의 과정을 경험하게 된다.",
