   "goals": "본 강의는 현대사회에서 여가 활동과 레크리에이션의 필요성을 이해하고, 신체적, 정신적 건강을 증진시키는 방법을 탐색한다. 이론적 지식과 함께 다양한 여가 및 레크리에이션 활동을 직접 경험함으로써 올바른 여가생활을 함양할 수 있도록 돕는다. 2022 개정 교육과정의 핵심역량에 기반하여 학생들은 의미 있는 여가 시간의 활용과 긍정적 의사소통을 통한 인간관계 형성 및 사회적 네트워크 확장 능력을 기를 수 있다. 또한 개인 및 팀별 실습을 통해 자기관리 능력과 공동체 역량을 강화하며, 일상생활에서 행복하고 균형 잡힌 삶의 질을 향상시키는 데 기여하고자 한다.",
   "overview": "1. 현대사회에서 여가 활동과 레크레이션의 중요성을 이해할 수 있다. 2. 현대인의 생애주기별 다양한 여가 활동에 대한 이론적 지식을 탐색하고 습득할 수 있다. 3. 여가 및 레크레이션 활동을 통해 사회적 상호작용과 정서적 공감 및 협력 기술을 향상 시킬 수 있다. 4. 여가 및 레크레이션 체험활동을 통해 일상생활에서도 지속할 수 있다.",
