   "overview": "학기 초에는 도가 철학, 곧 노자와 장자의 철학을 개론적으로 소개한다. 이후에는 주교재 <강신주의 장자 수업> 첫째 권을 중심으로 <장자>의 내용을 공부한다. 이를 통해 자유와 해방, 진리와 인식, 성인과 덕(德) 등의 주제에 관해 함께 논의해 본다. 주교재 첫째 권 진도를 마친 후에, 주교재 둘째 권의 내용을 바탕으로 간단히 조별 발표 또는 개인 발표를 진행한다.(중간시험 대체) 학기 후반부에는 AI 시대인 오늘날, 장자의 사유와 철학이 어떻게 인간과 문명, 기술과 진보, 자아와 타자에 관한 등에 관해 새로운 성찰을 제시할 수 있는지 함께 고민해 본다.",
