   "evaluation": "출석 10%, 중간고사 대체과제 20%, 에세이 20%, 기말고사 20%, 5분발표 10%, 토의토론 20%",
   "textbook": "(주교재) 강의자료 / (부교재1) 박승희, 우충완, 박지연, 김원영 공역(2016). 장애란 무엇인가: 장애학 입문. 학지사. / (부교재2) 김원영(2018). 실격당한 자들을 위한 변론. 도서출판 사계절. / (부교재3) 박찬선, 장세희 공저(2022). 경계선 지능을 가진 아이들. 이담북스.",
   "goals": "본 교과목은 대학생의 사회 다양성과 포용에 관한 이해와 인식 증진을 교수 목표로 한다. 1. 우리 사회에 만연한 편견, 고정관념, 차별 등에 대한 균형 있는 비판 능력을 육성하고, 장애와 비장애의 경계선에서 발생하는 여러 가지 사회 문제들에 대한 통합적 이해력과 공감 능력을 기를 수 있다. 2. 문제의 해결을 위한 다각적 시각을 기르고 기초적 지식을 습득하여 사회 제 문제에 대한 참여의식을 높이고 비판적 사고와 실천력을 강화할 수 있다. 3. 다양성의 시대에서 포용적인 사회의 일원이 되기 위한 인지적, 정서적 준비과정을 통해 자아 정체성을 확립하고 인간 다양성을 이해하고 연대감을 향상할 수 있다. 4. '차이'에 대한 고정관념을 학생 스스로 깨고 경계선 주변에 놓여있는 소수자들을 존중하고 인정하며 포용할 수 있다.",
