   "goals": "본 강의의 목표는 반려인구 1500만 시대, 인간과 가장 가까운 곳에서 함께 살아가는 반려동물을 최근 부상하는 동물권의 관점에서 성찰해보는 것이다. 반려동물과 인간이 가정, 사회, 자연 속에서 대면하게 되는 다양한 문제점들을 함께 토론한다. 이를 통해, 동물학대의 배후에 놓인 인간중심주의, 종차별주의를 넘어, 우리가 반려동물과 공존/소통할 수 있는 삶을 그려본다.",
