   "goals": "본 강의는 \"개인적인 것이 정치적인 것이다\"라는 테제를 바탕으로, 사적 감정인 '사랑'이 어떻게 사회적·역사적 맥락 속에서 형성되는지 탐구한다. 코로나19 이후 심화된 대면 소통의 공포와 젠더 갈등으로 인한 '관계 회피' 현상을 직시하고, 이를 극복하기 위한 대안으로서 사랑을 제안한다. 수강생들은 이론적 학습과 예술 비평, 실전 데이트, 비폭력 대화 연습을 통해 자신을 이해하고 타자를 존중하는 법을 배울 수 있다.",
   "overview": "본 강의에서는 사랑과 연애를 개인의 감정 경험이나 찰나의 이벤트에 국한하지 않고 철학, 역사, 과학, 문화, 역사학의 관점에서 통합하여 이해하고자 한다. 수강생들은 시대에 따라 달라지는 사랑의 개념의 유동성과 역사적 변화를 탐색하고, 현대 사회에서 형성된 연애 문화와 관계의 특징을 비판적으로 파악할 수 있다. 본 강의는 이론 중심 학습에 그치지 않고, 실제 데이트를 기획하고 실행하는 프로젝트 기반 학습(Project-Based Learning)을 포함하여 학습자의 실천적 능력을 강화한다. 학기 초에 조를 편성하여 수업 중에 조별 데이트 코스와 내용을 기획하고 1회의 실전 데이트 시행 후 보고서를 작성한다.",
